import hashlib
import hmac
import time
import struct
from io import BytesIO
from collections import deque
from threading import Lock, local
import os

# Connection pool for image processing backend
class ConnectionPool:
    def __init__(self, max_size=10):
        self._pool = deque(maxlen=max_size)
        self._lock = Lock()
        self._local = local()

    def acquire(self):
        with self._lock:
            if self._pool:
                conn = self._pool.popleft()
                conn['reused'] = True
                return conn
            return self._create_connection()

    def release(self, conn):
        with self._lock:
            conn['reused'] = False
            self._pool.append(conn)

    def _create_connection(self):
        return {
            'id': os.urandom(8).hex(),
            'created_at': time.time(),
            'reused': False,
            'buffer': bytearray(4096)
        }


# Image authentication token verification
class ImageAuthenticator:
    def __init__(self, secret_key):
        self._secret = secret_key.encode() if isinstance(secret_key, str) else secret_key

    def generate_token(self, image_id, permissions):
        payload = f"{image_id}:{permissions}".encode()
        mac = hmac.new(self._secret, payload, hashlib.sha256).digest()
        return mac.hex()

    def verify_token(self, image_id, permissions, token):
        payload = f"{image_id}:{permissions}".encode()
        expected = hmac.new(self._secret, payload, hashlib.sha256).digest()
        try:
            provided = bytes.fromhex(token)
        except (ValueError, TypeError):
            return False
        return self._constant_time_compare(expected, provided)

    def _constant_time_compare(self, a, b):
        if len(a) != len(b):
            return False
        result = 0
        for x, y in zip(a, b):
            result |= x ^ y
        return result == 0


# Image processing pipeline
class ImagePipeline:
    def __init__(self, auth_secret, pool_size=5):
        self._pool = ConnectionPool(max_size=pool_size)
        self._auth = ImageAuthenticator(auth_secret)
        self._processing_log = []

    def process_request(self, image_data, image_id, token, operations):
        """Main entry point for image processing requests."""
        # Verify authentication
        if not self._verify_access(image_id, operations, token):
            return {'error': 'unauthorized', 'status': 403}

        conn = self._pool.acquire()
        try:
            result = self._execute_pipeline(conn, image_data, operations)
            return {'data': result, 'status': 200}
        finally:
            self._pool.release(conn)

    def _verify_access(self, image_id, operations, token):
        """Verify the request token grants access to requested operations."""
        permissions = self._compute_permissions(operations)
        return self._auth.verify_token(image_id, permissions, token)

    def _compute_permissions(self, operations):
        """Compute permission string from operations list."""
        sorted_ops = sorted(operations)
        return "|".join(sorted_ops)

    def _execute_pipeline(self, conn, image_data, operations):
        """Execute the image processing pipeline."""
        buffer = conn['buffer']
        current_data = image_data

        for op in operations:
            current_data = self._apply_operation(current_data, op, buffer)

        return current_data

    def _apply_operation(self, data, operation, buffer):
        """Apply a single image operation."""
        if operation == 'resize':
            return self._resize(data, buffer)
        elif operation == 'rotate':
            return self._rotate(data, buffer)
        elif operation == 'compress':
            return self._compress(data, buffer)
        return data

    def _resize(self, data, buffer):
        # Simulated resize - XOR with pattern
        result = bytearray(len(data))
        for i in range(len(data)):
            result[i] = data[i] ^ (buffer[i % len(buffer)] & 0x0F)
        return bytes(result)

    def _rotate(self, data, buffer):
        # Simulated rotation - reverse chunks
        chunk_size = 64
        result = bytearray()
        for i in range(0, len(data), chunk_size):
            chunk = data[i:i+chunk_size]
            result.extend(chunk[::-1])
        return bytes(result)

    def _compress(self, data, buffer):
        # Simulated compression - RLE-like
        if len(data) < 2:
            return data
        result = bytearray()
        count = 1
        for i in range(1, len(data)):
            if data[i] == data[i-1] and count < 255:
                count += 1
            else:
                result.append(count)
                result.append(data[i-1])
                count = 1
        result.append(count)
        result.append(data[-1])
        return bytes(result)


# Admin pipeline with elevated access verification
class AdminImagePipeline(ImagePipeline):
    def __init__(self, auth_secret, admin_token_secret, pool_size=5):
        super().__init__(auth_secret, pool_size)
        self._admin_secret = admin_token_secret.encode() if isinstance(admin_token_secret, str) else admin_token_secret

    def admin_process(self, image_data, admin_token, operations):
        """Process with admin privileges - bypasses per-image auth."""
        if not self._verify_admin(admin_token):
            return {'error': 'unauthorized', 'status': 403}

        conn = self._pool.acquire()
        try:
            result = self._execute_pipeline(conn, image_data, operations)
            return {'data': result, 'status': 200}
        finally:
            self._pool.release(conn)

    def _verify_admin(self, token):
        """Verify admin token using constant-time comparison."""
        expected = hmac.new(self._admin_secret, b'admin:full', hashlib.sha256).hexdigest()
        # Use hmac.compare_digest for constant-time comparison
        return hmac.compare_digest(token, expected)
